<?php require_once __DIR__ . '/../includes/functions.php'; admin_header('Orders'); $file=basename(__FILE__); $rows=db_fetch_all("SELECT o.*,pc.case_code,p.full_name FROM orders o JOIN patient_cases pc ON pc.id=o.case_id JOIN patients p ON p.id=o.patient_id ORDER BY o.id DESC LIMIT 100"); $cols=['order_code', 'case_code', 'full_name', 'status', 'payment_method', 'created_at']; ?><div class="card soft-card"><div class="card-body table-responsive"><table class="table table-hover"><thead><tr><?php foreach($cols as $c): ?><th><?= e(str_replace('_',' ',ucfirst($c))) ?></th><?php endforeach; ?><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><?php foreach($cols as $c): ?><td><?= e(excerpt((string)($r[$c] ?? ''), 120)) ?></td><?php endforeach; ?><?php if($file==='orders.php') echo '<td><a class="btn btn-sm btn-outline-success" href="order-view.php?id='.(int)$r['id'].'">View</a></td>'; elseif($file==='prescriptions.php') echo '<td><a class="btn btn-sm btn-outline-success" href="prescription-review.php?print='.(int)$r['id'].'">Print</a></td>'; else echo '<td></td>'; ?></tr><?php endforeach; ?></tbody></table><?php if(!$rows) echo empty_state('No records found.'); ?></div></div><?php admin_footer(); ?>
